INSERT OR IGNORE INTO resources (id,title,author,publisher,category,level,description,image_url,link_url,is_published,sort_order) VALUES
(1,'طراحی زندگی (Designing Your Life)','بیل برنت و دیو ایوانز','','مسیر شغلی','پایه','رویکرد طراحی برای ساخت یک زندگی و مسیر شغلی با پروتوتایپ و آزمایش کوچک.','','',1,1),
(2,'رنگ چتر تو چیست؟ (What Color Is Your Parachute?)','ریچارد بولز','','مسیر شغلی','پایه','راهنمای پرکاربرد شناخت مهارت‌ها و جست‌وجوی شغل.','','',1,2),
(3,'ذهنیت (Mindset)','کارول دوئک','','انگیزه','پایه','ذهنیت رشد در برابر ذهنیت ثابت و اثر آن بر یادگیری.','','',1,3),
(4,'عادت‌های اتمی (Atomic Habits)','جیمز کلیر','','عادت و برنامه‌ریزی','پایه','ساختن عادت‌های کوچک ولی پایدار.','','',1,4),
(5,'پشتکار (Grit)','آنجلا داکورث','','انگیزه','پایه','نقش علاقه و پشتکار بلندمدت در موفقیت.','','',1,5),
(6,'کار عمیق (Deep Work)','کال نیوپورت','','تمرکز','متوسط','تمرکز عمیق در دنیای پر از حواس‌پرتی.','','',1,6),
(7,'Make It Stick','براون، رودیگر و مک‌دانیل','','روش مطالعه','متوسط','خلاصه‌ی پژوهش‌های یادگیری مؤثر مثل خودآزمایی و مرور فاصله‌دار.','','',1,7),
(8,'A Mind for Numbers','باربارا اوکلی','','روش مطالعه','پایه','یادگیری ریاضی و علوم برای همه.','','',1,8),
(9,'آنقدر خوب باش که نتوانند نادیده‌ات بگیرند (So Good They Can''t Ignore You)','کال نیوپورت','','مسیر شغلی','متوسط','اهمیت مهارت ارزشمند در ساختن شغل رضایت‌بخش.','','',1,9),
(10,'Range','دیوید اپشتین','','مسیر شغلی','متوسط','چرا تنوع تجربه و شروع غیرخطی می‌تواند مفید باشد.','','',1,10);
INSERT OR IGNORE INTO articles (id,slug,title,category,summary,body,image_url,author,is_published,published_at) VALUES
(1,'how-to-choose-major','چطور رشته‌ی تحصیلی انتخاب کنیم؟','انتخاب رشته','یک چارچوب ساده برای تصمیم‌گیری آگاهانه.','انتخاب رشته را می‌توان به چهار گام تقسیم کرد. گام اول شناخت خود است: علایق، توانایی‌ها و ارزش‌هایت را با تست‌ها و بازتاب شخصی بشناس. گام دوم شناخت گزینه‌هاست: چند رشته و شغل را با جزئیات بخوان و با شاغلان گفت‌وگو کن. گام سوم سنجش است: مزایا، چالش‌ها و انطباق هر گزینه با ارزش‌هایت را بنویس. گام چهارم آزمایش کوچک است: پیش از تصمیم نهایی یک کارگاه، دوره‌ی کوتاه یا پروژه‌ی مرتبط را امتحان کن. یادت باشد تصمیم شغلی یک مسیر است نه یک نقطه؛ می‌توان در طول زمان آن را اصلاح کرد.','','تیم مسیر من',1,'2025-01-01'),
(2,'common-mistakes','اشتباهات رایج در انتخاب رشته','انتخاب رشته','چند دام تصمیم‌گیری که خوب است بشناسی.','اشتباه اول انتخاب فقط بر اساس درآمد یا اعتبار اجتماعی است بدون توجه به علاقه و توانایی. اشتباه دوم تقلید از دوستان یا خانواده. اشتباه سوم نداشتن اطلاعات دقیق از محتوای درسی رشته است؛ خیلی از رشته‌ها با اسمشان متفاوت‌اند. اشتباه چهارم انتظار قطعیت کامل است؛ هیچ‌کس آینده را دقیق نمی‌داند. راه‌حل: اطلاعات بگیر، با شاغلان صحبت کن، گزینه‌ی جایگزین (پلن B) داشته باش و تصمیم را با اقدام‌های کوچک بیازمای.','','تیم مسیر من',1,'2025-01-01'),
(3,'coach-counselor-mentor','تفاوت کوچ، مشاور و منتور','کوچینگ','سه نقش مکمل با کارکردهای متفاوت.','مشاور به تصمیم‌گیری کمک می‌کند: گزینه‌ها را روشن می‌کند و راهنمایی تخصصی می‌دهد. منتور تجربه‌ی واقعی خودش را منتقل می‌کند: کسی که مسیر را رفته و از پیچ‌ها آگاه است. کوچ به تبدیل تصمیم به اقدام و پیگیری آن کمک می‌کند: هدف را خرد می‌کند، گزارش می‌گیرد و مانع‌ها را با تو بررسی می‌کند. بسته به مرحله‌ی زندگی ممکن است به هر سه نیاز داشته باشی.','','تیم مسیر من',1,'2025-01-01'),
(4,'evidence-based-study','روش‌های مطالعه‌ی مبتنی بر شواهد','مطالعه','دو روش که پژوهش‌ها بارها تأیید کرده‌اند.','پژوهش‌های یادگیری نشان می‌دهند خودآزمایی (بازیابی فعال) و مرور فاصله‌دار از خواندن مکرر و خط‌کشیدن مؤثرترند. یعنی بعد از خواندن، کتاب را ببند و آنچه یادت مانده را بنویس یا بگو؛ سپس همان مطلب را بعد از یک روز، چند روز و یک هفته دوباره مرور کن. خواب کافی و استراحت‌های کوتاه هم به تثبیت حافظه کمک می‌کنند.','','تیم مسیر من',1,'2025-01-01'),
(5,'konkur-stress','مدیریت استرس دوران کنکور','سلامت','چند راهکار ساده برای کاهش فشار.','کمی استرس طبیعی و حتی مفید است، اما استرس زیاد تمرکز را کم می‌کند. خواب منظم، فعالیت بدنی، تقسیم درس‌ها به بلوک‌های کوچک و تمرین تنفس آهسته کمک می‌کند. به جای مقایسه با دیگران، پیشرفت خودت را ثبت کن. اگر اضطراب زیاد یا طولانی شد یا اختلال خواب و اشتها پیدا کردی، حتماً با مشاور یا پزشک صحبت کن و تنها نمان.','','تیم مسیر من',1,'2025-01-01');
