INSERT OR IGNORE INTO faqs (id,category,question,answer,sort_order,is_active) VALUES
(1,'عمومی','«مسیر من» دقیقاً چه کاری می‌کند؟','با تست‌ها، اطلاعات رشته و شغل، برنامه‌ی مطالعه، کوچینگ و مشاوره کمک می‌کند مسیر آینده‌ات را بشناسی و اجرا کنی.',1,1),
(2,'عمومی','آیا نتیجه‌ی تست‌ها قطعی است؟','خیر. نتیجه‌ها ابزار خودشناسی و شروع گفت‌وگو هستند و جایگزین تصمیم شخصی یا نظر متخصص نیستند.',2,1),
(3,'خدمات','چرا خدمات انسانی پولی هستند؟','ارائه‌دهندگان وقت و تخصص خود را اختصاص می‌دهند. پیش از ثبت درخواست همیشه قیمت به شما نمایش داده می‌شود.',3,1),
(4,'پرداخت','پرداخت چگونه انجام می‌شود؟','در نسخه‌ی فعلی کارت‌به‌کارت است؛ شماره‌ی پیگیری را ثبت می‌کنی و پس از تأیید مدیر، درخواست فعال می‌شود.',4,1),
(5,'دعوت دوستان','دعوت دوستان چگونه تخفیف می‌دهد؟','لینک دعوت خودت را بفرست؛ وقتی دوستت با آن ثبت‌نام کند برای هر دو نفر کوپن تخفیف ساخته می‌شود.',5,1);
